    tay                             ; $8DEB
    lda     statMeter               ; $8DEC
    sec                             ; $8DEF
    sbc     SpellCosts - 1,y        ; $8DF0  y = spell * 8 + magic level (1-8)
    bcc     @loc_8E3B               ; $8DF3

@loc_8DF5:
